func calorieClass(cal, budget float64) string {
	if budget <= 0 {
		return "cal-good"
	}
	if cal > budget*1.1 {
		return "cal-over"
	}
	if cal < budget*0.6 {
		return "cal-low"
	}
	return "cal-good"
}

